import{_ as t,C as s,o as e,c as u,j as i,E as n,a as o,a2 as r}from"./chunks/framework.C21TwvGF.js";const M=JSON.parse(`{"title":"15-dars (Mentor). UI dizayn: tugmalar, menyular, HUD (2-qism): Bosh menyu, sozlamalar va pauza menyusi dizayni","description":"","frontmatter":{"title":"15-dars (Mentor). UI dizayn: tugmalar, menyular, HUD (2-qism): Bosh menyu, sozlamalar va pauza menyusi dizayni","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":5,"link":"/mentor/9-sinf-game/hafta-05/"},"g":15,"title":"UI dizayn: tugmalar, menyular, HUD (2-qism): Bosh menyu, sozlamalar va pauza menyusi dizayni","lead":"O'yin bilan birinchi uchrashuv — bosh menyu. U o'yinchiga «xush kelibsiz» deydi va yo'l ko'rsatadi. Bugun o'yiningiz uchun bosh menyu va pauza menyusini yaratamiz.","slide":"/slaydlar/9-sinf-game/hafta-05/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-05/dars-3-test.html","student_link":"/9-sinf-game/hafta-05/dars-3","tabs":[{"g":13,"link":"/mentor/9-sinf-game/hafta-05/dars-1","current":false},{"g":14,"link":"/mentor/9-sinf-game/hafta-05/dars-2","current":false},{"g":15,"link":"/mentor/9-sinf-game/hafta-05/dars-3","current":true}],"prev":{"g":14,"title":"UI dizayn: tugmalar, menyular, HUD (1-qism): Tugmalar turlari, holatlari (Normal, Hover, Pressed)","link":"/mentor/9-sinf-game/hafta-05/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-05/dars-3.md","filePath":"mentor/9-sinf-game/hafta-05/dars-3.md"}`),h={name:"mentor/9-sinf-game/hafta-05/dars-3.md"},m={class:"blk"},d={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},y={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},b={class:"blk"},p={id:"tezkor-nazorat-savollari",tabindex:"-1"},c={class:"blk"},v={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function f(z,a,_,P,S,T){const l=s("Icon");return e(),u("div",null,[i("div",m,[i("h2",d,[n(l,{name:"file-text"}),a[0]||(a[0]=o(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga menyu tushunchasini va menyu turlarini (asosiy menyu, sozlamalar menyusi, o&#39;yin ichidagi pauza menyusi), gorizontal va vertikal menyularni, ikonka va matn uyg&#39;unligini, rang va effektlarni qo&#39;llashni o&#39;rgatish; uslubiy ko&#39;rsatma bo&#39;yicha Photoshop&#39;da START, Sozlamalar, Chiqish tugmalaridan iborat to&#39;liq asosiy menyuni yaratish va eksport qilish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar uchta menyu turining vazifasini va tarkibini ayta oladi; 1920×1080 hujjatda MENU sarlavhasi, 3 ta tugma, Solid Color fon va bezak doiralaridan iborat bosh menyuni yaratadi; qatlamlarni guruhlaydi (<code>Ctrl + G</code>) va nomlaydi; sozlamalar yoki pauza menyusi eskizini tuzadi; natijani PNG/JPG qilib eksport qiladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>Takrorlash (tugma turlari va holatlari): 10 daqiqa</li><li>Yangi mavzu: menyu tushunchasi va turlari, gorizontal/vertikal: 15 daqiqa</li><li>Ikonka va matn uyg&#39;unligi, rang va effektlar: 10 daqiqa</li><li>Amaliyot: Photoshop&#39;da bosh menyu (uslubiy ko&#39;rsatma bo&#39;yicha): 25 daqiqa</li><li>Amaliyot: pauza yoki sozlamalar menyusi, eksport: 15 daqiqa</li><li>Xulosa: 5 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «Menyu turlari ... Photoshopda menyular dizayni. Gorizontal va vertikal menyular. Icon va matn uyg&#39;unligi. Rang va effektlarni qo&#39;llash»; o&#39;quv qo&#39;llanma — 2.4-bo&#39;lim (menyu ta&#39;rifi; Main Menu, Settings Menu, Pause Menu; «Menyular uchun panel dizayni, iconlar, matn joylashuvi va rang uyg&#39;unligi ishlanadi. Har bir bo&#39;lim (masalan, &quot;Play&quot;, &quot;Settings&quot;, &quot;Exit&quot;) uchun alohida tugmalar ... yaratiladi»; 6-bosqich — guruhlash <code>Ctrl+G</code>); uslubiy ko&#39;rsatma — 1.4-mashg&#39;ulot (1.88–1.106-rasmlar: tugmani dublikat qilish, «Sozlamalar», «Chiqish» — qizil, Solid Color fon, MENU sarlavhasi, guruhlash, Ellipse Tool bezaklari, Export As). HUD batafsil — keyingi darslar.</p></blockquote><hr>",3))]),i("div",g,[i("h2",y,[n(l,{name:"file-text"}),a[3]||(a[3]=o(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r(`<h3 id="_1-menyu-nima" tabindex="-1">1. Menyu nima? <a class="header-anchor" href="#_1-menyu-nima" aria-label="Permalink to &quot;1. Menyu nima?&quot;">​</a></h3><p>O&#39;quv qo&#39;llanma: <strong>Menyu</strong> — foydalanuvchi o&#39;yin imkoniyatlari orasida tanlov qiladigan tuzilma. U interfeysning <strong>tashkiliy va navigatsion</strong> qismi bo&#39;lib, o&#39;yinchi uchun boshqaruv tizimini ta&#39;minlaydi.</p><h3 id="_2-menyu-turlari" tabindex="-1">2. Menyu turlari <a class="header-anchor" href="#_2-menyu-turlari" aria-label="Permalink to &quot;2. Menyu turlari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tur</th><th>Qachon ochiladi</th><th>Tarkibi (namuna)</th></tr></thead><tbody><tr><td><strong>Asosiy menyu (Main Menu)</strong></td><td>o&#39;yin ishga tushganda</td><td>O&#39;yinni boshlash, Sozlamalar, Chiqish</td></tr><tr><td><strong>Sozlamalar menyusi (Settings Menu)</strong></td><td>asosiy yoki pauza menyusidan</td><td>tovush, grafika, boshqaruv variantlari</td></tr><tr><td><strong>O&#39;yin ichidagi menyu (Pause Menu)</strong></td><td>o&#39;yin jarayonida (Esc / pauza tugmasi)</td><td>Davom etish, Sozlamalar, Bosh menyuga chiqish</td></tr></tbody></table><p>Bog&#39;lanish: Main Menu → Settings → (Ortga) → Main Menu; O&#39;yin → Pause → Davom etish → O&#39;yin. Har ekranda <strong>ortga yo&#39;l</strong> bo&#39;lishi kerak.</p><h3 id="_3-gorizontal-va-vertikal-menyular" tabindex="-1">3. Gorizontal va vertikal menyular <a class="header-anchor" href="#_3-gorizontal-va-vertikal-menyular" aria-label="Permalink to &quot;3. Gorizontal va vertikal menyular&quot;">​</a></h3><ul><li><strong>Vertikal menyu:</strong> tugmalar ustma-ust, bir xil masofada. Bosh menyu va pauza uchun eng ko&#39;p ishlatiladi — o&#39;qish tartibi tepadan pastga, eng muhimi tepada.</li><li><strong>Gorizontal menyu:</strong> tugmalar yonma-yon. Bo&#39;limlar (tablar) uchun qulay: sozlamalarda «Tovush | Grafika | Boshqaruv», do&#39;konda kategoriyalar, pastki navigatsiya paneli (mobil).</li></ul><h3 id="_4-ikonka-va-matn-uyg-unligi" tabindex="-1">4. Ikonka va matn uyg&#39;unligi <a class="header-anchor" href="#_4-ikonka-va-matn-uyg-unligi" aria-label="Permalink to &quot;4. Ikonka va matn uyg&#39;unligi&quot;">​</a></h3><ul><li>Ikonka matnni <strong>to&#39;ldiradi</strong>, almashtirmaydi (yangi o&#39;yinchi uchun matn aniqroq).</li><li>Bir xil o&#39;lcham, bir xil uslub (11-dars ikonkalari), ikonka matndan chapda, vertikal markazda.</li><li>Bir xil masofa: ikonka — matn oralig&#39;i barcha tugmalarda teng.</li><li>Kichik ekranda faqat ikonka qolsa, u hammaga tanish bo&#39;lsin (tishli g&#39;ildirak — sozlamalar, uy — bosh menyu).</li></ul><h3 id="_5-rang-va-effektlar" tabindex="-1">5. Rang va effektlar <a class="header-anchor" href="#_5-rang-va-effektlar" aria-label="Permalink to &quot;5. Rang va effektlar&quot;">​</a></h3><ul><li>Fon — sokin (Solid Color yoki xira o&#39;yin sahnasi), tugmalar — fondan ajraladi.</li><li>Primary (START) — eng yorqin; Chiqish — qizil (uslubiy ko&#39;rsatmada ham shunday), boshqalari — neytralroq.</li><li>Effektlar (Layer Styles): Drop Shadow, Outer Glow, gradient — me&#39;yorida.</li><li>Pauza menyusida orqada <strong>o&#39;yin sahnasi xiralashtirilgan</strong> yoki qorong&#39;ilashtirilgan bo&#39;ladi — o&#39;yinchi qayerda to&#39;xtaganini ko&#39;radi.</li></ul><h3 id="_6-photoshop-bosh-menyu-uslubiy-ko-rsatma-bo-yicha" tabindex="-1">6. Photoshop: bosh menyu (uslubiy ko&#39;rsatma bo&#39;yicha) <a class="header-anchor" href="#_6-photoshop-bosh-menyu-uslubiy-ko-rsatma-bo-yicha" aria-label="Permalink to &quot;6. Photoshop: bosh menyu (uslubiy ko&#39;rsatma bo&#39;yicha)&quot;">​</a></h3><ol><li>14-darsdagi «O&#39;yin menyusi» (1920×1080) hujjati: START tugmasi tayyor.</li><li><strong>Dublikat:</strong> tugma shakli va matn qatlamini <code>Shift</code> bilan birga belgilab, Move Tool (V) bilan <code>Shift + Alt</code> bosib pastga suriladi — nusxa paydo bo&#39;ladi.</li><li>Nusxa biroz kichraytiriladi, matni <strong>«Sozlamalar»</strong> ga o&#39;zgartiriladi, Properties orqali matn o&#39;lchami va shakl rangi o&#39;zgartiriladi.</li><li>Yana dublikat → <strong>«Chiqish»</strong>, rangi <strong>qizil</strong>. Tugmalar <strong>vertikal, bir xil masofada</strong>.</li><li><strong>Fon:</strong> Layers → yangi <strong>Solid Color</strong> (fill layer) → eng pastki qatlamga → mos rang.</li><li><strong>Sarlavha:</strong> START matnini <code>Ctrl + J</code> bilan nusxalab, yuqoriga qo&#39;yiladi, matni <strong>«MENU»</strong>, o&#39;lchami kattaroq; qatlam Solid Color&#39;dan yuqorida.</li><li><strong>Guruhlash:</strong> shakllar va matnlar <code>Shift</code> bilan belgilanadi → <code>Ctrl + G</code> → guruh nomi <strong>Main Menu</strong> yoki <strong>Buttons</strong>.</li><li>Guruh Move Tool bilan markazga.</li><li><strong>Bezak:</strong> Ellipse Tool (U), <code>Shift</code> bilan mukammal doira; kattalashtirish, rang; <code>Alt</code> bilan sudrab nusxalar.</li><li><strong>Eksport:</strong> File → Export → <strong>Export As</strong> → PNG yoki JPG. Uslubiy ko&#39;rsatma: JPG — hajm kichik, taqdimot va namoyish uchun qulay; o&#39;yin ichida alohida elementlar (shaffof) — PNG.</li></ol><h3 id="_7-pauza-menyusi-qo-shimcha-amaliyot" tabindex="-1">7. Pauza menyusi (qo&#39;shimcha amaliyot) <a class="header-anchor" href="#_7-pauza-menyusi-qo-shimcha-amaliyot" aria-label="Permalink to &quot;7. Pauza menyusi (qo&#39;shimcha amaliyot)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Pause Menu (Group)</span></span>
<span class="line"><span>  fon_xira       o&#39;yin skrinshoti + Black qatlam, Opacity 60%</span></span>
<span class="line"><span>  panel          Rounded Rectangle, Stroke, Drop Shadow</span></span>
<span class="line"><span>  sarlavha       &quot;PAUZA&quot;</span></span>
<span class="line"><span>  btn_davom      Primary (yashil)</span></span>
<span class="line"><span>  btn_sozlama    oddiy</span></span>
<span class="line"><span>  btn_chiqish    qizil — &quot;Bosh menyuga&quot;</span></span></code></pre></div><h3 id="_8-sozlamalar-menyusi-eskizi" tabindex="-1">8. Sozlamalar menyusi eskizi <a class="header-anchor" href="#_8-sozlamalar-menyusi-eskizi" aria-label="Permalink to &quot;8. Sozlamalar menyusi eskizi&quot;">​</a></h3><ul><li>Gorizontal tablar: <strong>Tovush | Grafika | Boshqaruv</strong>.</li><li>Tovush: Musiqa va Effektlar uchun slayder (progress bar ko&#39;rinishi), Grafika: sifat (Past/O&#39;rta/Yuqori), to&#39;liq ekran (on/off).</li><li>Pastda: <strong>Ortga</strong> (Secondary) va <strong>Saqlash</strong> (Primary).</li></ul><hr>`,18))]),i("div",k,[i("h2",q,[n(l,{name:"file-text"}),a[6]||(a[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-menyu-turlari-oson" tabindex="-1">1-topshiriq. Menyu turlari (oson) <a class="header-anchor" href="#_1-topshiriq-menyu-turlari-oson" aria-label="Permalink to &quot;1-topshiriq. Menyu turlari (oson)&quot;">​</a></h3><p>Quyidagi tugmalar qaysi menyuga tegishli: «Davom etish», «Musiqa ovozi», «O&#39;yinni boshlash», «Grafika sifati», «Bosh menyuga chiqish», «Chiqish».</p><p><strong>Yechim:</strong> Asosiy menyu: O&#39;yinni boshlash, Chiqish. Sozlamalar: Musiqa ovozi, Grafika sifati. Pauza menyusi: Davom etish, Bosh menyuga chiqish. (Sozlamalar tugmasi asosiy va pauza menyusida ham bo&#39;ladi.)</p><h3 id="_2-topshiriq-bosh-menyu-oson" tabindex="-1">2-topshiriq. Bosh menyu (oson) <a class="header-anchor" href="#_2-topshiriq-bosh-menyu-oson" aria-label="Permalink to &quot;2-topshiriq. Bosh menyu (oson)&quot;">​</a></h3><p>Uslubiy ko&#39;rsatma bo&#39;yicha START, Sozlamalar, Chiqish tugmalaridan iborat vertikal menyu yarating.</p><p><strong>Yechim:</strong> 14-dars START tugmasi → Shift+Alt bilan 2 marta dublikat → matnlar «Sozlamalar», «Chiqish» → Chiqish rangi qizil → tugmalar orasidagi masofa teng (masalan, 40 px). Tekshirish: Align (Move Tool panelidagi Align horizontal centers) bilan markazlangan.</p><h3 id="_3-topshiriq-to-liq-bosh-menyu-o-rta" tabindex="-1">3-topshiriq. To&#39;liq bosh menyu (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-to-liq-bosh-menyu-o-rta" aria-label="Permalink to &quot;3-topshiriq. To&#39;liq bosh menyu (o&#39;rta)&quot;">​</a></h3><p>2-topshiriqqa Solid Color fon, «MENU» sarlavhasi, 2 ta bezak doira qo&#39;shing, guruhlang va PNG qilib eksport qiling.</p><p><strong>Yechim:</strong></p><ol><li>Layer → New Fill Layer → Solid Color → eng pastga.</li><li>START matni Ctrl + J → yuqoriga → «MENU», ~120 pt.</li><li>Shakl va matnlar → Ctrl + G → nomi «Main Menu» → markazga.</li><li>Ellipse Tool + Shift → doira → Alt bilan nusxa → burchaklarga, fon rangidan biroz ochroq.</li><li>File → Export → Export As → PNG <code>bosh_menyu.png</code>. Tekshirish: sarlavha va tugmalar fondan aniq ajraladi.</li></ol><h3 id="_4-topshiriq-pauza-menyusi-qiyin" tabindex="-1">4-topshiriq. Pauza menyusi (qiyin) <a class="header-anchor" href="#_4-topshiriq-pauza-menyusi-qiyin" aria-label="Permalink to &quot;4-topshiriq. Pauza menyusi (qiyin)&quot;">​</a></h3><p>O&#39;yin sahnasi ustida pauza menyusini yarating: xiralashtirilgan fon, panel, «PAUZA» sarlavhasi, 3 tugma (Davom etish — Primary, Sozlamalar, Bosh menyuga — qizil), ikonka + matn.</p><p><strong>Yechim:</strong></p><ul><li>Fon: o&#39;yin skrinshoti (yoki 10-dars lokatsiyasi) + qora Solid Color, Opacity 60% (yoki Filter → Blur → Gaussian Blur).</li><li>Panel: Rectangle, Corners 30 px, Stroke 4 px, Drop Shadow.</li><li>Tugmalar: 14-dars uslubi; chap tomonda 11-dars ikonkalari (play, tishli g&#39;ildirak, uy), ikonka–matn oralig&#39;i teng.</li><li>Guruh «Pause Menu», eksport PNG. Tekshirish: Davom etish — eng ko&#39;zga tashlanadigan; Bosh menyuga — qizil va pastda.</li></ul><hr>',15))]),i("div",b,[i("h2",p,[n(l,{name:"file-text"}),a[9]||(a[9]=o(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Menyu nima? <ul><li><em>Javob:</em> O&#39;yinchi o&#39;yin imkoniyatlari orasida tanlov qiladigan tashkiliy va navigatsion tuzilma.</li></ul></li><li>Uchta menyu turini ayting. <ul><li><em>Javob:</em> Asosiy (Main), Sozlamalar (Settings), O&#39;yin ichidagi (Pause).</li></ul></li><li>Vertikal va gorizontal menyu qachon ishlatiladi? <ul><li><em>Javob:</em> Vertikal — bosh va pauza menyusi; gorizontal — bo&#39;limlar/tablar (sozlamalar, do&#39;kon).</li></ul></li><li>Uslubiy ko&#39;rsatmada «Chiqish» tugmasi qaysi rangda? <ul><li><em>Javob:</em> Qizil.</li></ul></li><li>Photoshop&#39;da qatlamlar qanday guruhlanadi? <ul><li><em>Javob:</em> Shift bilan belgilab, Ctrl + G; guruhga nom beriladi.</li></ul></li></ol><hr>",2))]),i("div",c,[i("h2",v,[n(l,{name:"file-text"}),a[12]||(a[12]=o(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=r("<ul><li><strong>Tugmalar orasidagi masofa har xil:</strong> menyu tartibsiz — Align va teng oraliq.</li><li><strong>Ortga yo&#39;l yo&#39;q:</strong> Sozlamalardan chiqib bo&#39;lmaydi — har ekranda Ortga.</li><li><strong>Fon tugmalardan yorqin:</strong> tugmalar yo&#39;qolib qoladi — fon sokin.</li><li><strong>Ikonka va matn uslubi har xil:</strong> bir ikonka konturli, biri to&#39;liq — bir uslubga keltiring.</li><li><strong>Qatlamlar nomsiz:</strong> «Rectangle 1 copy 3» — guruhlang va nomlang.</li><li><strong>Pauza menyusida o&#39;yin to&#39;liq yashirilgan:</strong> o&#39;yinchi qayerda to&#39;xtaganini unutadi — xira, lekin ko&#39;rinadigan fon.</li></ul>",1))])])}const A=t(h,[["render",f]]);export{M as __pageData,A as default};
